<?php
$canEnterMarks=in_array($user['role'],['Administrator','Head','Teacher'],true);
$assignmentSql="SELECT cs.class_id,cs.subject_id,cs.teacher_id,c.class_teacher_id,c.form_level,c.stream,c.academic_year,s.subject_name,s.subject_code FROM class_subjects cs JOIN class_groups c ON c.id=cs.class_id JOIN subjects s ON s.id=cs.subject_id WHERE s.active=1";$assignmentParams=[];
if($user['role']==='Teacher'){$assignmentSql.=' AND (cs.teacher_id=:teacher OR c.class_teacher_id=:class_teacher)';$assignmentParams=['teacher'=>$user['id'],'class_teacher'=>$user['id']];}
$assignmentSql.=' ORDER BY c.academic_year DESC,c.form_level,c.stream,s.subject_name';$stmt=$pdo->prepare($assignmentSql);$stmt->execute($assignmentParams);$classSubjects=$stmt->fetchAll();
$terms=$pdo->query('SELECT id,academic_year,term_number,name,starts_on,ends_on,is_current FROM school_terms ORDER BY is_current DESC,academic_year DESC,term_number DESC')->fetchAll();
$assessmentId=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);$assessment=null;$markRows=[];$unmarked=0;
if($assessmentId){
  $stmt=$pdo->prepare('SELECT a.*,t.name AS term_name,t.academic_year,t.starts_on,t.ends_on,c.form_level,c.stream,c.academic_year AS class_year,s.subject_name,s.subject_code,cs.teacher_id,c.class_teacher_id FROM assessments a JOIN school_terms t ON t.id=a.term_id JOIN class_groups c ON c.id=a.class_id JOIN subjects s ON s.id=a.subject_id JOIN class_subjects cs ON cs.class_id=a.class_id AND cs.subject_id=a.subject_id WHERE a.id=:id');$stmt->execute(['id'=>$assessmentId]);$assessment=$stmt->fetch();
  if(!$assessment||(int)$assessment['class_year']!==(int)$assessment['academic_year']||($user['role']==='Teacher'&&(int)$assessment['teacher_id']!==(int)$user['id']&&(int)$assessment['class_teacher_id']!==(int)$user['id'])){$assessment=null;http_response_code(404);}
  if($assessment){$stmt=$pdo->prepare("SELECT DISTINCT s.id,s.admission_no,s.first_name,s.last_name,m.mark,m.mark_status,m.grade,m.comment FROM students s JOIN student_enrolments e ON e.student_id=s.id LEFT JOIN assessment_marks m ON m.student_id=s.id AND m.assessment_id=:assessment WHERE e.academic_year=:year AND e.form_level=:form AND COALESCE(e.stream,'')=:stream AND e.start_date<=:term_end AND (e.end_date IS NULL OR e.end_date>=:term_start) ORDER BY s.last_name,s.first_name");$stmt->execute(['assessment'=>$assessmentId,'year'=>$assessment['academic_year'],'form'=>$assessment['form_level'],'stream'=>$assessment['stream'],'term_end'=>$assessment['ends_on'],'term_start'=>$assessment['starts_on']]);$markRows=$stmt->fetchAll();foreach($markRows as $row)if($row['mark_status']===null)$unmarked++;}
}
$listSql='SELECT a.id,a.title,a.assessment_type,a.max_mark,a.held_on,t.name AS term_name,t.academic_year,c.form_level,c.stream,s.subject_name,s.subject_code,COUNT(m.student_id) AS marks_recorded FROM assessments a JOIN school_terms t ON t.id=a.term_id JOIN class_groups c ON c.id=a.class_id JOIN subjects s ON s.id=a.subject_id JOIN class_subjects cs ON cs.class_id=a.class_id AND cs.subject_id=a.subject_id LEFT JOIN assessment_marks m ON m.assessment_id=a.id';
$listParams=[];if($user['role']==='Teacher'){$listSql.=' WHERE cs.teacher_id=:teacher OR c.class_teacher_id=:class_teacher';$listParams=['teacher'=>$user['id'],'class_teacher'=>$user['id']];}
$listSql.=' GROUP BY a.id,a.title,a.assessment_type,a.max_mark,a.held_on,t.name,t.academic_year,c.form_level,c.stream,s.subject_name,s.subject_code ORDER BY COALESCE(a.held_on,t.starts_on) DESC,a.id DESC';$list=$pdo->prepare($listSql);$list->execute($listParams);$assessmentRows=$list->fetchAll();
?>
<?php if($assessment): ?>
  <div class="page-heading"><div><div class="eyebrow">MARKBOOK · <?= h($assessment['term_name']) ?> <?= (int)$assessment['academic_year'] ?></div><h1><?= h($assessment['title']) ?></h1><p class="subheading">Form <?= (int)$assessment['form_level'] ?><?= h($assessment['stream']) ?> · <?= h($assessment['subject_name']) ?> · Maximum <?= h(number_format((float)$assessment['max_mark'],2)) ?></p></div><a class="outline-button" href="?page=academics&tab=assessments">← Assessments</a></div>
  <div class="alert alert-warn grade-note">Enter marks using the school’s approved grading rules. The portal records raw marks and optional grades; it does not assume official ZIMSEC grade boundaries.</div>
  <section class="stat-strip"><div><span>Learners in class</span><b><?= count($markRows) ?></b></div><div><span>Marks recorded</span><b><?= count($markRows)-$unmarked ?></b></div><div><span>Not yet marked</span><b><?= $unmarked ?></b></div><div><span>Assessment type</span><b class="small-stat"><?= h($assessment['assessment_type']) ?></b></div></section>
  <form method="post" action="actions/assessment_marks_save.php" class="panel markbook-panel"><?= csrf_field() ?><input type="hidden" name="assessment_id" value="<?= (int)$assessmentId ?>"><div class="panel-heading"><div><h2>Learner marks</h2><p>Leave a learner unmarked to save marks in stages.</p></div><button class="primary-button">Save marks</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Admission no.</th><th>Status</th><th>Mark / <?= h(number_format((float)$assessment['max_mark'],2)) ?></th><th>Grade</th><th>Teacher comment</th></tr></thead><tbody><?php foreach($markRows as $row): ?><tr><td><div class="learner-cell"><span class="learner-avatar"><?= h(strtoupper(substr($row['first_name'],0,1).substr($row['last_name'],0,1))) ?></span><b><?= h($row['first_name'].' '.$row['last_name']) ?></b></div></td><td class="muted-cell"><?= h($row['admission_no']) ?></td><td><select class="mark-status" name="scores[<?= (int)$row['id'] ?>][status]"><option value="">Not entered</option><?php foreach(['Scored','Absent','Exempt'] as $status): ?><option <?= $row['mark_status']===$status?'selected':'' ?>><?= $status ?></option><?php endforeach; ?></select></td><td><input class="mark-input" type="number" name="scores[<?= (int)$row['id'] ?>][mark]" min="0" max="<?= h((string)$assessment['max_mark']) ?>" step="0.01" value="<?= $row['mark']===null?'':h((string)$row['mark']) ?>"></td><td><input class="grade-input" name="scores[<?= (int)$row['id'] ?>][grade]" maxlength="4" value="<?= h($row['grade']??'') ?>" placeholder="Optional"></td><td><input class="comment-input" name="scores[<?= (int)$row['id'] ?>][comment]" maxlength="255" value="<?= h($row['comment']??'') ?>" placeholder="Optional"></td></tr><?php endforeach; if(!$markRows): ?><tr><td colspan="6" class="empty-cell">No active learners are enrolled in this class group.</td></tr><?php endif; ?></tbody></table></div><div class="attendance-actions"><a class="text-button" href="?page=academics&tab=assessments">Back to assessments</a><button class="primary-button">Save marks</button></div></form>
<?php else: ?>
  <?php if($assessmentId): ?><div class="alert alert-error">That assessment is unavailable or is not assigned to your account.</div><?php endif; ?>
  <?php if($canEnterMarks): ?><section class="panel settings-panel assessment-create-panel"><h2>Create an assessment</h2><p>Choose the term, class and subject from the school’s configured teaching allocations.</p><?php if(!$terms||!$classSubjects): ?><div class="alert alert-warn">Set up academic terms and class subject allocations before creating assessments.</div><?php else: ?><form method="post" action="actions/assessment_create.php" class="inline-form assessment-form"><?= csrf_field() ?><label>Term<select name="term_id" required><option value="">Select term</option><?php foreach($terms as $term): ?><option value="<?= (int)$term['id'] ?>" <?= $term['is_current']?'selected':'' ?>><?= h($term['name']) ?> · <?= (int)$term['academic_year'] ?></option><?php endforeach; ?></select></label><label>Class & subject<select name="assignment" disabled hidden></select><select name="class_id" class="assignment-class" required><option value="">Select class + subject below</option><?php foreach($classSubjects as $entry): ?><option value="<?= (int)$entry['class_id'] ?>" data-subject="<?= (int)$entry['subject_id'] ?>">Form <?= (int)$entry['form_level'] ?><?= h($entry['stream']) ?> · <?= h($entry['subject_name']) ?> (<?= h($entry['subject_code']) ?>)</option><?php endforeach; ?></select></label><input type="hidden" name="subject_id" id="assessmentSubject"><label>Title<input name="title" required maxlength="120" placeholder="e.g. Term 2 Mathematics Test"></label><label>Type<select name="assessment_type"><?php foreach(['Test','Assignment','Practical','Coursework','Examination'] as $type): ?><option><?= h($type) ?></option><?php endforeach; ?></select></label><label>Maximum mark<input type="number" name="max_mark" required min="0.01" max="10000" step="0.01" value="100"></label><label>Date held<input type="date" name="held_on"></label><button class="primary-button">Create assessment</button></form><?php endif; ?></section><?php endif; ?>
  <section class="panel learners-panel"><div class="panel-heading"><div><h2>Assessments</h2><p>Continuous assessment, practicals, coursework and examinations</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Assessment</th><th>Class & subject</th><th>Term</th><th>Type</th><th>Maximum</th><th>Marks entered</th><th></th></tr></thead><tbody><?php foreach($assessmentRows as $a): ?><tr><td><b><?= h($a['title']) ?></b></td><td>Form <?= (int)$a['form_level'] ?><?= h($a['stream']) ?> · <?= h($a['subject_name']) ?></td><td><?= h($a['term_name']) ?> <?= (int)$a['academic_year'] ?></td><td><?= h($a['assessment_type']) ?></td><td><?= h(number_format((float)$a['max_mark'],2)) ?></td><td><?= (int)$a['marks_recorded'] ?></td><td><a class="text-button" href="?page=academics&tab=assessments&id=<?= (int)$a['id'] ?>">Open markbook →</a></td></tr><?php endforeach; if(!$assessmentRows): ?><tr><td colspan="7" class="empty-cell">No assessments yet. Configure terms and subject assignments, then create the first assessment.</td></tr><?php endif; ?></tbody></table></div></section>
<?php endif; ?>
<script>
document.querySelector('.assignment-class')?.addEventListener('change', function(){const option=this.selectedOptions[0];document.getElementById('assessmentSubject').value=option?.dataset.subject||'';});
</script>
